Window* xf_Pointer_get_window( XF_Pointer *xf_pointer ) { if ( !xf_pointer ) { WLog_Print_dbg_tag( "xf_Pointer: Invalid appWindow", 3,0xA0, "<stdin>", &__func__, "xf_Pointer: Invalid context" ); return NULL; } if ( xf_pointer->context ) { if ( !xf_pointer->map ) { WLog_Print_dbg_tag( "xf_Pointer: Invalid appWindow", 3,0xA7, "<stdin>", &__func__, "xf_Pointer: Invalid window" ); return NULL; } return xf_pointer->map->window; } if ( !xf_pointer->conn ) { WLog_Print_dbg_tag( "xf_Pointer: Invalid appWindow", 3,0xB0, "<stdin>", &__func__, "xf_Pointer: Invalid appWindow" ); return NULL; } return xf_pointer->conn->window; }